#include <bits/stdc++.h>
using namespace std;

#define int long long
#define all(v) v.begin(),v.end()
#define sz(x) (int)x.size()
#define INF LLONG_MAX



int M = 998244353;

vector<int> fact((int)5e5+1);

int subs_cnt(int idx,int sum,int target,vector<int> &c){
    if(sum > target) return 0;

    if(idx == sz(c)){
        if(sum == target) return 1;
        return 0;
    }

    sum += c[idx];
    int take = subs_cnt(idx+1,sum,target,c);
    sum -= c[idx];
    int notTake = subs_cnt(idx+1,sum,target,c);

    return take+notTake;
}

int modInverse(int x,int n){
   int res = 1;
   while(n > 0){
    if(n%2 == 1){
        res = (res*(x%M))%M;
    }

    x = ((x%M)*(x%M))%M;
    n /=2;
   }

   return res;
}

void solve() {
    vector<int> freq(26);
    vector<int> c;
    int x = 1;

    int mex = 0;

    for(int i = 0;i<26;i++){
        cin >> freq[i];
        x = x*fact[freq[i]]%M;
        mex = max(mex,2*(freq[i]-1)+1);
        if(freq[i] != 0){
            c.push_back(freq[i]);
        }
    }


    int n = accumulate(all(freq),0LL);

    if(n == 0){
        cout<<0<<"\n";
        return;
    }

    if(mex > n){
        cout<<0<<"\n";
        return;
    }

    //count the number of subsequences whose sum is n/2
    int cnt = subs_cnt(0,0,n/2,c);

    int ans = ((fact[(n+1)/2]*fact[n/2]%M)*(modInverse(x,M-2)%M)*cnt%M)%M;

    cout<<ans<<"\n";
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    fact[0] = 1;
    fact[1] = 1;

    for(int i = 2;i<=(int)5e5;i++){
        fact[i] = i*fact[i-1]%M;
    }

    int t;
    cin >> t;
    while(t--) solve();
    return 0;
}
